export function createDiagnostics({ initial = [], max = 80, persist, toast, list, health, dialog }) {
  let traces = Array.isArray(initial) ? initial.slice(-max) : [];
  function trace(level, code, message, details = {}) { const entry = { id: uid(), time: new Date().toISOString(), level, code, message, details: safe(details) }; traces.push(entry); traces = traces.slice(-max); persist(traces); if (level === 'error') console.error(`[${entry.id}] ${code}: ${message}`, details); else if (level === 'warn') console.warn(`[${entry.id}] ${code}: ${message}`, details); return entry.id; }
  function render(healthText = '') { health.textContent = healthText; const items = [...traces].reverse().map(t => { const el = document.createElement('article'); el.className = `trace-item ${t.level}`; const top = document.createElement('div'); top.className = 'trace-top'; const strong = document.createElement('strong'); strong.textContent = `${t.level.toUpperCase()} · ${t.code}`; const time = document.createElement('span'); time.textContent = new Date(t.time).toLocaleTimeString('vi-VN'); top.append(strong, time); const msg = document.createElement('div'); msg.textContent = t.message; const code = document.createElement('div'); code.className = 'trace-code'; code.textContent = `Trace ${t.id}${Object.keys(t.details || {}).length ? ` · ${JSON.stringify(t.details)}` : ''}`; el.append(top, msg, code); return el; }); list.replaceChildren(...items); if (!items.length) { const p = document.createElement('p'); p.className = 'meta'; p.textContent = 'Chưa có log.'; list.replaceChildren(p); } }
  async function copy() { const text = traces.map(t => `${t.time} ${t.level.toUpperCase()} ${t.code} [${t.id}] ${t.message} ${JSON.stringify(t.details)}`).join('\n'); try { await navigator.clipboard.writeText(text); toast('Đã copy diagnostic log.'); } catch { toast('Không copy được log trên trình duyệt này.'); } }
  function clear() { traces = []; persist(traces); render(health.textContent); }
  function open(healthText) { render(healthText); dialog.showModal(); }
  return { trace, render, copy, clear, open, details: error => ({ message: error?.message || String(error), code: error?.code || null, traceId: error?.traceId || null }) };
}
function safe(details) { try { return JSON.parse(JSON.stringify(details || {})); } catch { return { note: 'details-unserializable' }; } }
function uid() { return `t_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`.slice(-14); }
